import pandas as pd, numpy as np
df = pd.read_parquet('/beegfs2/scratch/rreider/genai4simpy/output/fischertechnik_lab_C/foamy-ancient-hornet/work_files/eventlog_cleaned.parquet')
for c in ['time:timestamp','operation_end_time']:
    df[c] = pd.to_datetime(df[c], format='ISO8601')
df = df.sort_values(['case','time:timestamp'])
# per case, ordered activity instances
rows=[]
for case, g in df.groupby('case'):
    g = g.sort_values('time:timestamp')
    ev = g[['time:timestamp','operation_end_time','concept:name','org:resource','lifecycle:transition','event_id']].values.tolist()
    # build instance list: start row gives start ts; complete row gives complete ts
    insts={}
    for r in ev:
        t,oe,act,res,tr,eid = r
        if tr=='start': insts[eid]={'act':act,'res':res,'start':t}
        elif tr=='complete':
            if eid in insts: insts[eid]['complete']=oe
    seq=[]
    for eid,i in insts.items():
        if 'complete' in i: seq.append(i)
    seq.sort(key=lambda i: i['start'])
    for j,i in enumerate(seq):
        if i['act'].startswith('/hbw'):
            # preceding vgr step in same case (immediately previous instance if vgr)
            prev = seq[j-1] if j>0 else None
            if prev is not None and prev['act']=='/vgr/pick_up_and_transport':
                gap = (i['start'] - prev['complete']).total_seconds()
                rows.append({'case':case,'hbw_act':i['act'],'hbw_res':i['res'],'vgr_res':prev['res'],'gap_s':gap})
h = pd.DataFrame(rows)
print("hbw steps preceded by vgr:", len(h))
# resource busy intervals
busy = df[df['lifecycle:transition'].isin(['start','complete'])].copy()
busy['t'] = busy['time:timestamp']
busy = busy.sort_values('t')
# build per-resource busy intervals from start->complete
iv = {}
